krb5_error_code krb5int_pkinit_validate_kdc_pkid(krb5_context context,
                                                pkinit_plg_crypto_context plg_cryptoctx,
                                                pkinit_req_crypto_context req_cryptoctx,
                                                pkinit_identity_crypto_context id_cryptoctx,
                                                unsigned char *pdid_buf,
                                                unsigned int pkid_len,
                                                int *valid_kdcPkId) {
    krb5_error_code kret = 0;
    krb5_data pdid_data;
    pkinit_kdc_pkid kdc_pkid = {0};

    pdid_data.data = (char *)pdid_buf;
    pdid_data.length = pkid_len;

    if ((kret = pkinit_decode_kdc_pkid(context, &pdid_data, &kdc_pkid)))
        goto cleanup;

    if (id_cryptoctx->kdc_issuer == NULL || id_cryptoctx->kdc_serial == NULL) {
        *valid_kdcPkId = 0;
        kret = KRB5_PLUGIN_NO_HANDLE;
        goto cleanup;
    }

    if (kdc_pkid.issuer.length != id_cryptoctx->kdc_issuer->length ||
        memcmp(kdc_pkid.issuer.data, id_cryptoctx->kdc_issuer->data, kdc_pkid.issuer.length) != 0) {
        *valid_kdcPkId = 0;
        kret = KRB5_PLUGIN_NO_HANDLE;
        goto cleanup;
    }

    if (kdc_pkid.serial.length != sizeof(id_cryptoctx->kdc_serial->serial_number) ||
        memcmp(kdc_pkid.serial.data, &id_cryptoctx->kdc_serial->serial_number, kdc_pkid.serial.length) != 0) {
        *valid_kdcPkId = 0;
        kret = KRB5_PLUGIN_NO_HANDLE;
        goto cleanup;
    }

    *valid_kdcPkId = 1;

cleanup:
    if (kdc_pkid.issuer.data)
        free(kdc_pkid.issuer.data);
    if (kdc_pkid.serial.data)
        free(kdc_pkid.serial.data);
    return kret;
}

krb5_error_code check_kdc_public_key_identifier(krb5_context context,
                                               pkinit_plg_crypto_context plg_cryptoctx,
                                               pkinit_req_crypto_context req_cryptoctx,
                                               pkinit_identity_crypto_context id_cryptoctx,
                                               unsigned char *pdid_buf,
                                               unsigned int pkid_len,
                                               int *valid_kdcPkId) {
    krb5_error_code retval = 0;
    pkinit_kdc_info_t kdc_info = NULL;
    krb5_principal kdc_principal = NULL;
    krb5_data *decoded_id = NULL;

    *valid_kdcPkId = 0;

    /* Decode the public key identifier from the buffer */
    decoded_id = krb5_data_alloc(context, pkid_len);
    if (!decoded_id) {
        retval = ENOMEM;
        goto cleanup;
    }

    memcpy(decoded_id->data, pdid_buf, pkid_len);

    /* Retrieve KDC certificate information */
    if (plg_cryptoctx->pkinit_get_kdc_info(context, plg_cryptoctx, req_cryptoctx, id_cryptoctx, &kdc_info) != 0) {
        retval = KRB5_PLUGIN_GENERIC_ERROR;
        goto cleanup;
    }

    if (kdc_info == NULL) {
        retval = KRB5_PLUGIN_GENERIC_ERROR;
        goto cleanup;
    }

    /* Compare the identifier with the KDC certificate issuer and serial number */
    if (pkinit_compare_cert_info(context, decoded_id, kdc_info->cert_info) != 0) {
        goto cleanup;
    }

    *valid_kdcPkId = 1;

cleanup:
    if (decoded_id) {
        krb5_data_free(decoded_id);
    }
    if (kdc_info) {
        pkinit_free_kdc_info(context, kdc_info);
    }
    if (kdc_principal) {
        krb5_principal_free(context, kdc_principal);
    }

    return retval;
}

krb5_error_code check_kdc_public_key_identifier(
    krb5_context context,
    pkinit_plg_crypto_context plg_cryptoctx,
    pkinit_req_crypto_context req_cryptoctx,
    pkinit_identity_crypto_context id_cryptoctx,
    unsigned char *pdid_buf,
    unsigned int pkid_len,
    int *valid_kdcPkId)
{
    krb5_error_code krc = 0;
    krb5_data pdid_data = {0};
    pkinit_pvd_common common = {0};
    krb5_principal kdc_princ = NULL;
    krb5_X509_CERTIFICATE *cert = NULL;
    krb5_principal issuer = NULL;
    krb5_principal cert_issuer = NULL;
    krb5_boolean issuer_match = FALSE;
    krb5_crypto crypto = NULL;
    krb5_keyblock *keyblock = NULL;
    krb5_keyblock *pubkey = NULL;

    pdid_data.data = pdid_buf;
    pdid_data.length = pkid_len;

    krc = pkinit_locate_common(context, plg_cryptoctx, req_cryptoctx, &common);
    if (krc)
        goto cleanup;

    krc = krb5_unparse_name(context, common->kdc_princ, &kdc_princ);
    if (krc)
        goto cleanup;

    krc = id_cryptoctx->crypto->decode_PKINIT_PUBLICKEYDATA(
        context,
        pdid_data,
        &cert,
        NULL);
    if (krc)
        goto cleanup;

    krc = krb5_X509_get_issuer(context, cert, &issuer);
    if (krc)
        goto cleanup;

    krc = krb5_unparse_name(context, issuer, &cert_issuer);
    if (krc)
        goto cleanup;

    issuer_match = (strcmp(kdc_princ, cert_issuer) == 0);

    *valid_kdcPkId = (cert->tbsCertificate.serialNumber.length > 0) && issuer_match;

cleanup:
    if (kdc_princ)
        krb5_free_unparsed_name(context, kdc_princ);
    if (cert_issuer)
        krb5_free_unparsed_name(context, cert_issuer);
    if (issuer)
        krb5_free_principal(context, issuer);
    if (cert)
        krb5_X509_free_certificate(context, cert);

    return krc;
}

krb5_error_code verify_kdc_public_key_identifier(krb5_context context,
                                                 pkinit_plg_crypto_context plg_cryptoctx,
                                                 pkinit_req_crypto_context req_cryptoctx,
                                                 pkinit_identity_crypto_context id_cryptoctx,
                                                 unsigned char *pdid_buf,
                                                 unsigned int pkid_len,
                                                 int *valid_kdcPkId) {
    krb5_error_code k5ret = 0;
    krb5_data pdid_data;
    krb5_principal kdc_princ = NULL;
    krb5_X509_CERTIFICATE *cert = NULL;
    krb5_X509_NAME issuer_name = NULL;
    krb5_data serial_number = {0, NULL};
    int is_valid = 0;

    pdid_data.data = (char *)pdid_buf;
    pdid_data.length = pkid_len;

    k5ret = krb5_dk_read_kdc_pkid(context, &pdid_data, &kdc_princ);
    if (k5ret != 0) {
        goto cleanup;
    }

    cert = id_cryptoctx->cert;
    if (!cert) {
        k5ret = KRB5_PLUGIN_GENERICERROR;
        goto cleanup;
    }

    issuer_name = &cert->issuer;
    serial_number = cert->serial_number;

    k5ret = krb5_kdc_pkid_match(context, kdc_princ, issuer_name, &serial_number, &is_valid);
    if (k5ret != 0) {
        goto cleanup;
    }

    *valid_kdcPkId = is_valid;

cleanup:
    if (kdc_princ)
        krb5_free_principal(context, kdc_princ);
    return k5ret;
}

krb5_error_code validate_kdc_public_key_identifier(krb5_context context, pkinit_plg_crypto_context plg_cryptoctx,
                                                   pkinit_req_crypto_context req_cryptoctx,
                                                   pkinit_identity_crypto_context id_cryptoctx,
                                                   unsigned char *pdid_buf, unsigned int pkid_len,
                                                   int *valid_kdcPkId) {
    krb5_error_code kret = 0;
    krb5_data pdid_data;
    pkinit_pkeyid pkeyid = NULL;
    krb5_X509_CERTIFICATE *kdc_cert = NULL;
    krb5_X509_NAME issuer_name = NULL;
    krb5_X509_ASN1_INTEGER *serial = NULL;

    *valid_kdcPkId = 0;

    pdid_data.data = (char *)pdid_buf;
    pdid_data.length = pkid_len;

    if ((kret = pkinit_decode_PKINIT_PKEYID(context, &pdid_data, &pkeyid))) {
        goto cleanup;
    }

    if ((kret = krb5_pk_identity_get_kdc_cert(context, id_cryptoctx->pk_identity, &kdc_cert))) {
        goto cleanup;
    }

    if ((kret = krb5_X509_get_issuer_name(context, kdc_cert, &issuer_name))) {
        goto cleanup;
    }

    serial = krb5_X509_certificate_get_serial_number(kdc_cert);
    if (!serial) {
        kret = KRB5_CRYPTO_INTERNAL;
        goto cleanup;
    }

    if (pkeyid->issuer != NULL && pkeyid->serial_number != NULL &&
        issuer_name != NULL && serial != NULL) {
        if (krb5_X509_NAME_compare(context, pkeyid->issuer, issuer_name) == 0 &&
            krb5_X509_ASN1_INTEGER_equal(pkeyid->serial_number, serial)) {
            *valid_kdcPkId = 1;
        }
    }

cleanup:
    if (pkeyid) {
        pkinit_free_PKINIT_PKEYID(context, pkeyid);
    }
    if (kdc_cert) {
        krb5_X509_free_certificate(context, kdc_cert);
    }
    if (issuer_name) {
        krb5_X509_NAME_free(context, issuer_name);
    }

    return kret;
}
